import hashlib
img = open('/app/code.png','rb').read()
h0 = hashlib.sha256(img).digest()

def sha256_hexstr(s): return hashlib.sha256(s.encode()).hexdigest()
def sha256_bytes(b): return hashlib.sha256(b).hexdigest()

salts = ['0000BENCH-SALT','0000TBENCH-SALT']
prefixes = {
 'hex10': h0.hex()[:10],
 'hex8': h0.hex()[:8],
 'hex16': h0.hex()[:16],
 'bytes10': h0[:10],
}
for pn,p in prefixes.items():
    for s in salts:
        if isinstance(p,str):
            H = sha256_hexstr(p+s)
        else:
            H = sha256_bytes(p+s.encode())
        print(f'{pn} + {s}: {H}')
EOF

